  );
  IF n <> 2 THEN
    RAISE EXCEPTION 'migration 1899: the 2 update keys are not at their recorded Season 2 values (found %)', n;
  END IF;

  -- Every topic written must be pinned in Season 2 at the revision used.
  SELECT count(*) INTO n FROM (SELECT DISTINCT topic_id, topic_revision_id FROM (VALUES
