    ('c1ac1330-47f7-44ec-baf3-c913d926b97c'::uuid, '0e9fe0f2-cfab-4553-99cd-c3195d08e236'::uuid),
    ('c267e137-0ff9-4e7d-9d13-e3cea1756cd0'::uuid, 'f63a4e70-055e-4115-a5e0-3deeb5748816'::uuid),
    ('cab61e8a-64fe-4bbd-bc08-fe9914d0091b'::uuid, '38bab357-9790-4cb3-a6d2-c43cbdca615b'::uuid),
    ('d1792200-1d3b-4955-a0b7-0e6980d7a7b2'::uuid, '2a18c152-67a0-4380-a381-cb8795110a7c'::uuid),
    ('d4f18138-a2e0-4110-b925-7387d9d0d16d'::uuid, 'ef2a5e59-525a-41fa-94de-ce771df7c927'::uuid),
    ('e8dad4a8-eb93-4931-91f5-d8fb5d7dd529'::uuid, 'afc91aa2-4d48-4db6-aebd-f4c9788e6ad7'::uuid),
    ('f1e44d66-5d27-4b51-b54f-b7ace86f6a3c'::uuid, '5f1403f3-90b6-491f-ba54-3c8e46a5ae26'::uuid),
    ('f7e5678d-dadd-4556-a2fc-446e24642ceb'::uuid, '87f8c011-5c70-4f39-a1ea-5cc53c010c60'::uuid)
  ) AS v(topic_id, topic_revision_id)) w
  WHERE NOT EXISTS (SELECT 1 FROM inform.season_questions sq WHERE sq.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'
                     AND sq.topic_id = w.topic_id AND sq.topic_revision_id = w.topic_revision_id);
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1899: % written topics are not pinned in Season 2 at the stated revision', n;
  END IF;

  -- The three repairs keep Season 1's chair 4, so Season 2 climate-change rung 4 must still
  -- read as the market-decides rung that was compared against Season 1 before carrying it.
  SELECT count(*) INTO n FROM inform.compass_stance_revisions r
   WHERE r.topic_revision_id = (SELECT sq.topic_revision_id FROM inform.season_questions sq
          JOIN inform.compass_topics t ON t.id = sq.topic_id
         WHERE sq.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND t.topic_key = 'climate-change')
     AND r.value = 4 AND r.text ILIKE '%market%';
