    RAISE EXCEPTION 'migration 1899: Season 2 climate-change rung 4 is no longer the market rung -- re-read before repairing (found %)', n;
  END IF;

  -- The blocked keys ride on `immigration`, which still has NO Season 2 pin.
  SELECT count(*) INTO n FROM inform.season_questions sq JOIN inform.compass_topics t ON t.id = sq.topic_id
   WHERE sq.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND t.topic_key = 'immigration';
