INSERT INTO inform.politician_context
  (politician_id, topic_id, season_id, topic_revision_id, reasoning, sources)
VALUES
  -- Adrian C. Madaro / local-environment  (Season 1 chair 1 -> 0, TRUE_BUT_LADDER_SCOPE)
  ('290ee018-6e9e-4a8c-9561-385cf5ef3d73'::uuid, '1935979c-b290-42e4-baa5-8cb0138b4ffa'::uuid, '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid, 'd67eabf7-8da0-4ca7-b2af-74745b3bfd47'::uuid, 'Blanked 2026-10-07, and ⚠ THE UNDERLYING CLAIM IS TRUE -- it is recorded here so it is not lost. Madaro IS on the Cosponsors page of H.4264 of the 191st General Court, "An Act relative to environmental justice in the commonwealth" (Adrian C. Madaro is listed first, as an original petitioner). TWO THINGS ARE STILL WRONG. 🔴 THE CITATION POINTS AT THE WRONG BILL: the row cites H.4264 of the 192nd, which is "An Act establishing a year-round market rate rental housing trust in the town of Truro". And the bill that IS meant died -- "No further action taken", 1/5/2021 -- so it was never "signed into law in 2021" as this row states; the environmental justice provisions reached the statute book inside S.9, the climate roadmap. 🔴🔴 AND THE SEASON 2 LADDER ASKS SOMETHING STRONGER THAN THE EVIDENCE SUPPORTS. Season 1 rung 1 read "Require significant green space, tree preservation, and environmental review before approving any development"; Season 2 rung 1 reads "Make environmental protection the overriding priority -- block or sharply limit development that would harm the local environment". Co-sponsoring a cumulative-impact review bill for environmental justice communities is not evidence of blocking development, so carrying the chair across would seat this member on a position never assessed. That is the Carson/campaign-finance call from migration 1896, and it belongs to the ladder-scope register. A verified fact with nowhere to sit is still a verified fact: it is written here so the next researcher starts from it rather than from nothing. The sources examined are kept below so the next reader does not re-derive this. This is a blank, not a deletion -- the chair may well be re-researchable, and that is an invitation.', ARRAY['https://malegislature.gov/Bills/191/H4264/Cosponsor', 'https://malegislature.gov/Bills/192/H4264', 'https://malegislature.gov/Legislators/Profile/ACM1']::text[]),
  -- Brian W. Murray / climate-change  (Season 1 chair 2 -> 0, NOT_DISTINCTIVE)
  ('4702bc3c-0820-42f4-a0ae-5bc244c44159'::uuid, 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c'::uuid, '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid, '5f1403f3-90b6-491f-ba54-3c8e46a5ae26'::uuid, 'Blanked 2026-10-07. 🔴🔴 THE CITED BILL IS A MUNICIPAL HOUSING TRUST, NOT THE CLIMATE ROADMAP. The 2021 climate roadmap is S.9 of the 192nd General Court, "An Act creating a next-generation roadmap for Massachusetts climate policy". H.4264 of the 192nd -- the bill this row actually cites -- is "An Act establishing a year-round market rate rental housing trust in the town of Truro". The number is right for a different General Court: H.4264 of the 191st is "An Act relative to environmental justice in the commonwealth" -- but that bill DIED, "No further action taken" on 1/5/2021, and its sponsor is the Joint Committee on Environment, Natural Resources and Agriculture, not any individual member. 🔴 AND THE REAL INSTRUMENT CANNOT SEAT THIS CHAIR EITHER. S.9 passed the House 144 YEAS to 14 NAYS (Roll Call No. 2, 28 January 2021, verified against the roll call''s own declared totals) and the Senate 39 to 1. 🔑 A near-unanimous vote cannot establish a DISTINCTIVE position -- the rule that blanked Newhouse on 385-41 in migration 1894 and Dingell on 417-10 in 1896. 91% of the House voted the same way, so a Yea distinguishes this member from almost nobody. ⚠ THE CONVERSE DOES NOT HOLD, and three rows in this same cluster were REPAIRED rather than blanked for exactly that reason: dissenting from a 91% majority IS distinctive, and the 14 Nays are named in the roll call. The sources examined are kept below so the next reader does not re-derive this. This is a blank, not a deletion -- the chair may well be re-researchable, and that is an invitation.', ARRAY['https://malegislature.gov/Legislators/Profile/BWM1/Bills', 'https://malegislature.gov/Bills/192/H4264']::text[]),
  -- Bruce J. Ayers / climate-change  (Season 1 chair 2 -> 0, NOT_DISTINCTIVE)
  ('3582a053-ee20-4391-904f-3905a2d13a52'::uuid, 'f1e44d66-5d27-4b51-b54f-b7ace86f6a3c'::uuid, '86d893a1-c1a2-4bbf-b4e5-69ec43221194'::uuid, '5f1403f3-90b6-491f-ba54-3c8e46a5ae26'::uuid, 'Blanked 2026-10-07. 🔴🔴 THE CITED BILL IS A MUNICIPAL HOUSING TRUST, NOT THE CLIMATE ROADMAP. The 2021 climate roadmap is S.9 of the 192nd General Court, "An Act creating a next-generation roadmap for Massachusetts climate policy". H.4264 of the 192nd -- the bill this row actually cites -- is "An Act establishing a year-round market rate rental housing trust in the town of Truro". The number is right for a different General Court: H.4264 of the 191st is "An Act relative to environmental justice in the commonwealth" -- but that bill DIED, "No further action taken" on 1/5/2021, and its sponsor is the Joint Committee on Environment, Natural Resources and Agriculture, not any individual member. 🔴 AND THE REAL INSTRUMENT CANNOT SEAT THIS CHAIR EITHER. S.9 passed the House 144 YEAS to 14 NAYS (Roll Call No. 2, 28 January 2021, verified against the roll call''s own declared totals) and the Senate 39 to 1. 🔑 A near-unanimous vote cannot establish a DISTINCTIVE position -- the rule that blanked Newhouse on 385-41 in migration 1894 and Dingell on 417-10 in 1896. 91% of the House voted the same way, so a Yea distinguishes this member from almost nobody. ⚠ THE CONVERSE DOES NOT HOLD, and three rows in this same cluster were REPAIRED rather than blanked for exactly that reason: dissenting from a 91% majority IS distinctive, and the 14 Nays are named in the roll call. The sources examined are kept below so the next reader does not re-derive this. This is a blank, not a deletion -- the chair may well be re-researchable, and that is an invitation.', ARRAY['https://web.archive.org/web/20251114032517/https://actonmass.org/legislators/bruce-ayers/', 'https://malegislature.gov/Bills/192/H4264']::text[]),
  -- Chynah Tyler / local-environment  (Season 1 chair 1 -> 0, TRUE_BUT_LADDER_SCOPE)
